const html = `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8" />
<meta name="viewport" content="width=device-width, initial-scale=1.0" />
<title>3D Collect Game</title>
<style>
  html, body { margin:0; height:100%; overflow:hidden; background:#000; }
  canvas { display:block; }
  #ui {
    position:absolute; top:10px; left:10px; color:#fff;
    font-family: system-ui, sans-serif; font-size:18px;
    background: rgba(0,0,0,0.6); padding:8px 12px; border-radius:8px;
    backdrop-filter: blur(4px);
  }
  #gameover {
    position:absolute; top:50%; left:50%; transform:translate(-50%,-50%);
    color:#fff; font-family: system-ui, sans-serif; font-size:36px;
    background: rgba(0,0,0,0.8); padding:24px 32px; border-radius:12px;
    display:none; text-align:center;
  }
</style>
</head>
<body>
<div id="ui">Score: <span id="score">0</span> | Time: <span id="time">60</span></div>
<div id="gameover"></div>
<script type="importmap">
{
  "imports": {
    "three": "https://unpkg.com/three@0.160.0/build/three.module.js"
  }
}
</script>
<script type="module">
import * as THREE from 'three';

const scene = new THREE.Scene();
scene.background = new THREE.Color(0x0a0a12);
scene.fog = new THREE.Fog(0x0a0a12, 30, 120);

const camera = new THREE.PerspectiveCamera(70, innerWidth/innerHeight, 0.1, 1000);
camera.position.set(0, 8, 18);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(devicePixelRatio);
document.body.appendChild(renderer.domElement);

addEventListener('resize', () => {
  camera.aspect = innerWidth/innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});

// Lights
scene.add(new THREE.AmbientLight(0xffffff, 0.6));
const dir = new THREE.DirectionalLight(0xffffff, 1);
dir.position.set(10,20,10);
scene.add(dir);

// Ground
const ground = new THREE.Mesh(
  new THREE.PlaneGeometry(200,200),
  new THREE.MeshStandardMaterial({ color:0x222233, roughness:1 })
);
ground.rotation.x = -Math.PI/2;
scene.add(ground);

// Grid
scene.add(new THREE.GridHelper(200, 40, 0x444466, 0x222233));

// Player
const playerGeo = new THREE.BoxGeometry(1,1,1);
const playerMat = new THREE.MeshStandardMaterial({ color:0x00ff88 });
const player = new THREE.Mesh(playerGeo, playerMat);
player.position.y = 0.5;
scene.add(player);

// Collectibles
const collectibles = [];
const coinGeo = new THREE.SphereGeometry(0.4, 16,16);
for(let i=0;i<40;i++){
  const mat = new THREE.MeshStandardMaterial({ color:0xffd700, emissive:0x553300, emissiveIntensity:0.5 });
  const coin = new THREE.Mesh(coinGeo, mat);
  coin.position.set(
    (Math.random()-0.5)*80,
    0.4,
    (Math.random()-0.5)*80
  );
  scene.add(coin);
  collectibles.push(coin);
}

// Input
const keys = {};
addEventListener('keydown', e => keys[e.code]=true);
addEventListener('keyup', e => keys[e.code]=false);

const speed = 0.25;
const playerVel = new THREE.Vector3();

function updatePlayer(){
  playerVel.set(0,0,0);
  if(keys['KeyW'] || keys['ArrowUp']) playerVel.z -= 1;
  if(keys['KeyS'] || keys['ArrowDown']) playerVel.z += 1;
  if(keys['KeyA'] || keys['ArrowLeft']) playerVel.x -= 1;
  if(keys['KeyD'] || keys['ArrowRight']) playerVel.x += 1;
  if(playerVel.lengthSq()>0){
    playerVel.normalize().multiplyScalar(speed);
    player.position.x += playerVel.x;
    player.position.z += playerVel.z;
  }
  // keep inside bounds
  player.position.x = Math.max(-90, Math.min(90, player.position.x));
  player.position.z = Math.max(-90, Math.min(90, player.position.z));
}

// UI
const scoreEl = document.getElementById('score');
const timeEl = document.getElementById('time');
const gameoverEl = document.getElementById('gameover');
let score = 0;
let timeLeft = 60;
let gameRunning = true;

// Camera follow
const camOffset = new THREE.Vector3(0,8,14);

let lastTime = performance.now();
function animate(now){
  requestAnimationFrame(animate);
  const dt = (now - lastTime)/1000;
  lastTime = now;

  if(gameRunning){
    updatePlayer();
    // collect
    for(let i=collectibles.length-1;i>=0;i--){
      const c = collectibles[i];
      if(player.position.distanceTo(c) < 1.2){
        scene.remove(c);
        collectibles.splice(i,1);
        score++;
        scoreEl.textContent = score;
        // small bump
        playerMat.emissive = new THREE.Color(0x003300);
        setTimeout(()=>playerMat.emissive.set(0x000000),100);
      }
    }
    // timer
    timeLeft -= dt;
    if(timeLeft <=0){
      timeLeft = 0;
      endGame();
    }
    timeEl.textContent = Math.ceil(timeLeft);
  }

  // camera follow
  const targetCamPos = player.position.clone().add(camOffset);
  camera.position.lerp(targetCamPos, 0.1);
  camera.lookAt(player.position.x, 1, player.position.z);

  renderer.render(scene, camera);
}
animate(performance.now());

function endGame(){
  gameRunning = false;
  gameoverEl.textContent = 'Game Over\\nScore: ' + score;
  gameoverEl.style.display = 'block';
}

</script>
</body>
</html>`;

await Deno.writeTextFile('game.html', html);
console.log('game.html written, size:', html.length);

// Verify unpkg dependencies are reachable
const res = await fetch('https://unpkg.com/three@0.160.0/build/three.module.js');
console.log('Three.js module reachable:', res.status === 200);
if(res.status === 200){
  const txt = await res.text();
  console.log('Three.js header:', txt.slice(0,80).replace(/\\n/g,' '));
}

