            {%- endfor -%}
            {%- set tname = rns.name -%}
        {%- endif -%}
        {{- '<|start|>tool ' + tname + '<|message|><tool_output name="' + tname + '">\n' -}}
        {{- render_content(message['content']) -}}
        {{- '\n</tool_output><|eot|>' -}}
    {%- elif role == 'assistant' -%}
