                    {{- '<|eom|>' -}}
                {%- endif -%}
            {%- endfor -%}
        {%- else -%}
            {%- set recipient = message.get('recipient') or 'user' -%}
            {%- set end_turn = message.get('end_turn') -%}
            {%- if end_turn is none -%}
                {%- set end_turn = not (recipient and recipient != 'user') -%}
            {%- endif -%}
            {{- '<|start|>assistant' -}}
            {%- if recipient -%}
                {{- ' to=' + recipient -}}
            {%- endif -%}
            {{- '<|message|>' -}}
            {{- render_content(message['content']) -}}
            {{- ('<|eot|>' if end_turn else '<|eom|>') -}}
        {%- endif -%}
    {%- endif -%}
{%- endfor -%}
{%- if add_generation_prompt -%}
    {{- '<|start|>assistant' -}}
{%- endif -%}

